+				it(`should retry fs.writeFile() calls that fail with ${code} so that all files get written`, async () => {
+					const maxOpenFiles = 20;
+					const written = new Set();
+					let openFiles = 0;
+
+					// simulates an operating system that limits how many files can be open at once
+					const writeFile = sinon.spy(async filePath => {
+						if (openFiles >= maxOpenFiles) {
+							throw Object.assign(
+								new Error(
+									`${code}: too many open files, open '${filePath}'`,
+								),
+								{ code },
+							);
+						}
+
+						openFiles++;
+						try {
+							await timers.setTimeout(1);
+							written.add(filePath);
+						} finally {
+							openFiles--;
+						}
+					});
+					const { ESLint: localESLint } = proxyquire(
+						"../../../lib/eslint/eslint",
+						{
+							"node:fs/promises": { writeFile },
+						},
+					);
+
+					const results = Array.from({ length: 500 }, (_, i) => ({
+						filePath: path.resolve(`file${i}.js`),
+						output: `output ${i}`,
+					}));
+
+					await localESLint.outputFixes(results);
+
+					assert.strictEqual(written.size, results.length);
+					results.forEach(({ filePath }) => {
+						assert(
+							written.has(filePath),
+							`${filePath} not written`,
+						);
+					});
+				});
+			});
+
+			it("should not start writing all files at the same time", async () => {
+				let inFlight = 0;
+				let maxInFlight = 0;
+				const writeFile = sinon.spy(async () => {
+					inFlight++;
+					maxInFlight = Math.max(maxInFlight, inFlight);
+					await timers.setTimeout(1);
+					inFlight--;
+				});
+				const { ESLint: localESLint } = proxyquire(
+					"../../../lib/eslint/eslint",
+					{
+						"node:fs/promises": { writeFile },
+					},
+				);
+
+				const results = Array.from({ length: 1000 }, (_, i) => ({
+					filePath: path.resolve(`file${i}.js`),
+					output: `output ${i}`,
+				}));
+
+				await localESLint.outputFixes(results);
+
+				assert.strictEqual(writeFile.callCount, results.length);
+				assert(
+					maxInFlight < results.length,
+					`Expected fewer than ${results.length} concurrent writes, but there were ${maxInFlight}`,
+				);
+			});
+
+			it("should reject if fs.writeFile() fails with an error that isn't EMFILE or ENFILE", async () => {
